import re
from collections import defaultdict

class INIParser:
    def __init__(self, text: str):
        self.text = text
        self.sections = defaultdict(dict)
        self.default = {}
        self.current_section = None
        self.section_stack = []
        self.parse()

    def parse(self):
        lines = self.text.splitlines()
        continuation = None
        in_multiline_string = False
        in_value_string = False

        for line in lines:
            line = line.strip()

            if not line or line.startswith(';') or line.startswith('#'):
                if in_value_string:
                    continuation = line
                continue

            if continuation:
                line = continuation + '\n' + line
                continuation = None

            if line.startswith((' ', '\t')) and not in_value_string:
                if in_multiline_string:
                    self.sections[self.current_section][current_key] += '\n' + line.lstrip()
                else:
                    raise ValueError("Invalid line continuation.")
                continue

            if line.startswith('[') and line.endswith(']'):
                section_name = line[1:-1].strip()
                if not section_name:
                    raise ValueError("Invalid section name.")
                self.current_section = section_name
                self.section_stack.append(section_name)
                continue

            if ':' in line or '=' in line:
                delimiter = ':' if ':' in line and '=' not in line else '='
                key, value = map(str.strip, line.split(delimiter, 1))

                if not key:
                    raise ValueError("Invalid key.")

                key = key.lower()

                if value.startswith('"') and value.endswith('"'):
                    in_value_string = True
                    value = value[1:-1]
                elif in_value_string:
                    value += '\n' + line.lstrip()
                    if value.endswith('"'):
                        in_value_string = False
                        value = value[:-1]
                    continue
                else:
                    in_value_string = False

                if ';' in value or '#' in value:
                    comment_start = min((value.find(c) for c in (';', '#') if value.find(c) != -1), default=-1)
                    if comment_start != -1:
                        value = value[:comment_start]

                if self.current_section:
                    self.sections[self.current_section][key] = value
                else:
                    self.default[key] = value

                current_key = key
                in_multiline_string = False
                continue

            if in_value_string:
                self.sections[self.current_section][current_key] += '\n' + line.lstrip()
                continue

            raise ValueError("Malformed line encountered.")

        self.resolve_interpolation()

    def resolve_interpolation(self):
        def interpolate(value, section_name):
            pattern = re.compile(r'\$\{([^}]+)\}')
            while True:
                match = pattern.search(value)
                if not match:
                    break

                full_match = match.group(0)
                key_path = match.group(1)
                if ':' in key_path:
                    section, key = key_path.split(':', 1)
                else:
                    section, key = section_name, key_path

                section = section.strip()
                key = key.strip()

                if section == 'DEFAULT':
                    if key in self.default:
                        replacement = self.default[key]
                    else:
                        raise KeyError(f"Missing key in DEFAULT: {key}")
                elif section in self.sections:
                    if key in self.sections[section]:
                        replacement = self.sections[section][key]
                    else:
                        raise KeyError(f"Missing key in section [{section}]: {key}")
                else:
                    raise KeyError(f"Missing section: [{section}]")

                visited_sections.add(section)
                value = value.replace(full_match, interpolate(replacement, section))
                visited_sections.remove(section)

                if section in visited_sections:
                    raise ValueError("Interpolation cycle detected.")

            return value

        visited_sections = set()

        for section, pairs in self.sections.items():
            for key, value in pairs.items():
                self.sections[section][key] = interpolate(value, section)

        for key, value in self.default.items():
            self.default[key] = interpolate(value, 'DEFAULT')

    def parse_ini(self):
        result = {}
        if self.sections:
            for section, pairs in self.sections.items():
                section_dict = {}
                for key, value in pairs.items():
                    section_dict[key] = value
                for key, value in self.default.items():
                    if key not in section_dict:
                        section_dict[key] = value
                result[section] = section_dict
        return result

def parse_ini(text: str) -> dict:
    parser = INIParser(text)
    return parser.parse_ini()
