import re

def parse_duration(s: str) -> int:
    # Regular expression to match the parts of the duration string
    pattern = re.compile(
        r'(?P<hours>\d+)\s*h\s*|\s*(?P<minutes>\d+)\s*m\s*|\s*(?P<seconds>\d+)\s*s\s*'
    )

    if not s.strip():
        raise ValueError("Empty or blank string")

    # Matching all parts
    matches = list(pattern.finditer(s))

    if not matches:
        raise ValueError("No valid duration parts found")

    # Dictionaries to hold the parsed values
    values = {
        'hours': None,
        'minutes': None,
        'seconds': None
    }

    for match in matches:
        for unit in ('hours', 'minutes', 'seconds'):
            if match.group(unit):
                if values[unit] is not None:
                    raise ValueError(f"Repeated unit '{unit}'")
                values[unit] = int(match.group(unit))

    # Check for units in the correct order
    order = ['hours', 'minutes', 'seconds']
    last_index = -1

    for unit in order:
        if values[unit] is not None:
            current_index = order.index(unit)
            if current_index < last_index:
                raise ValueError(f"Units out of order: '{unit}'")
            last_index = current_index
        elif last_index is not -1:
            # If current unit is None, and previous units are not None
            raise ValueError(f"Missing unit '{unit}' after '{order[last_index]}'")

    # Calculating total seconds
    total_seconds = 0
    if values['hours'] is not None:
        total_seconds += values['hours'] * 3600
    if values['minutes'] is not None:
        total_seconds += values['minutes'] * 60
    if values['seconds'] is not None:
        total_seconds += values['seconds']

    return total_seconds
